using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;

public class SpriteFixer
{
    public static void Fix()
    {
        string[] paths = new string[] {
            "Assets/Scenes/Credit/CreditBg.png",
            "Assets/Scenes/Credit/NameTagBoard.png",
            "Assets/Scenes/Credit/ArrowButton.png",
            "Assets/Scenes/Credit/BackButton.png"
        };

        foreach(var p in paths) {
            TextureImporter importer = AssetImporter.GetAtPath(p) as TextureImporter;
            if(importer != null && importer.textureType != TextureImporterType.Sprite) {
                importer.textureType = TextureImporterType.Sprite;
                importer.SaveAndReimport();
            }
        }

        var scene = EditorSceneManager.OpenScene("Assets/Scenes/Credit/CreditScene.unity", OpenSceneMode.Single);

        GameObject bgObj = GameObject.Find("Canvas/Background");
        if (bgObj != null) bgObj.GetComponent<Image>().sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Scenes/Credit/CreditBg.png");

        GameObject boardObj = GameObject.Find("Canvas/SlideContainer/NameTagBoard");
        if (boardObj != null) boardObj.GetComponent<Image>().sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Scenes/Credit/NameTagBoard.png");

        GameObject prevBtnObj = GameObject.Find("Canvas/SlideContainer/PrevButton");
        if (prevBtnObj != null) prevBtnObj.GetComponent<Image>().sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Scenes/Credit/ArrowButton.png");

        GameObject nextBtnObj = GameObject.Find("Canvas/SlideContainer/NextButton");
        if (nextBtnObj != null) nextBtnObj.GetComponent<Image>().sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Scenes/Credit/ArrowButton.png");

        GameObject backBtnObj = GameObject.Find("Canvas/BackButton");
        if (backBtnObj != null) backBtnObj.GetComponent<Image>().sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Scenes/Credit/BackButton.png");

        EditorSceneManager.SaveScene(scene);
    }
}
